('6256c37b-ccf9-4534-92f7-bc841b7ef740'::uuid, 'BOOLEAN', 'A data type whose values are TRUE or FALSE.', 'Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.', 'supplementary_targeted_verified', true),
('941cdea4-00e1-4562-9906-e9827295b674'::uuid, 'CHAR', 'A data type representing a single character.', 'Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.', 'supplementary_targeted_verified', true),
('104c1ec8-b4f2-48c6-a50d-5b45bc16240d'::uuid, 'DATE', 'A data type representing a valid calendar date.', 'Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.', 'supplementary_targeted_verified', true),
('6b542e43-c8f7-41a7-b453-8b38a0767d1a'::uuid, 'INTEGER', 'A data type representing whole numbers.', 'Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.', 'supplementary_targeted_verified', true),
('f2052294-0136-497f-bff1-8542ae5ed5cd'::uuid, 'REAL', 'A data type representing numbers that can include a fractional part.', 'Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.', 'supplementary_targeted_verified', true),
('ce24e284-6b9c-4b25-8f79-6fe8f7f05f32'::uuid, 'STRING', 'A data type representing a sequence of zero or more characters.', 'Hodder 9618 (2019), §10.1.1, p.240; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §2.1, p.7; 2027–2029 Pseudocode Guide, §2.1, p.7.', 'supplementary_targeted_verified', true),
('0c581b6f-2c35-4fa1-b483-48729fe82985'::uuid, 'EOF(file)', 'A function that returns TRUE when no more lines can be read from a file, and FALSE when more lines remain.', 'Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §9.1, p.25; 2027–2029 Pseudocode Guide, §9.1, p.25.', 'supplementary_targeted_verified', true),
('fc45e99e-835a-4aeb-b481-e59fe4f5c05f'::uuid, 'File mode', 'The access mode selected when a file is opened; READ retrieves data, WRITE writes data and replaces existing contents, and APPEND adds data after existing contents.', 'Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §9.1, p.25; 2027–2029 Pseudocode Guide, §9.1, p.25.', 'supplementary_targeted_verified', true),
('71a67e1e-8759-4dba-8607-ad1c0b0a2bd2'::uuid, 'Text file', 'A file that stores text as lines, which are read or written consecutively as strings.', 'Hodder 9618 (2019), §10.3, p.249; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.28; Cambridge 9618 Pseudocode Guide for Teachers (2026), §9.1, p.25; 2027–2029 Pseudocode Guide, §9.1, p.25.', 'supplementary_targeted_verified', true),
('90c47865-69c1-4cea-a080-f018c98de11a'::uuid, 'CASE statement', 'A selection statement that chooses the first matching branch according to the value of an identifier; an optional OTHERWISE branch runs if no case matches.', 'Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §6.2, p.19; 2027–2029 Pseudocode Guide, §6.2, p.19.', 'supplementary_targeted_verified', true),
('d50acf16-d1e5-41f3-b7d7-e25d3dea2396'::uuid, 'Count-controlled loop', 'A loop that executes its body for each integer value in a specified range, using a counter.', 'Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §7.1, p.20; 2027–2029 Pseudocode Guide, §7.1, p.20.', 'supplementary_targeted_verified', true),
('97295397-cd70-4c60-8b5d-3d2d692cd268'::uuid, 'IF statement', 'A selection statement that executes the THEN branch when a Boolean condition is TRUE and, when provided, the ELSE branch when it is FALSE.', 'Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §6.1, p.18; 2027–2029 Pseudocode Guide, §6.1, p.18.', 'supplementary_targeted_verified', true),
('e5eedbef-8caf-4b2c-bb97-c06a98a573a1'::uuid, 'Nested IF', 'An IF statement placed inside another IF or ELSE branch to test an additional condition within that branch.', 'Hodder 9618 (Watson & Williams, 2019), §11.2.1, p.272; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §6.1, p.18; 2027–2029 Pseudocode Guide, §6.1, p.18.', 'supplementary_targeted_verified', true),
('b0da2819-b53c-4ba1-a317-c69ed7b0f8b3'::uuid, 'Post-condition loop', 'A loop that tests its Boolean condition after executing its body, so the body runs at least once.', 'Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §7.2, pp.20–21; 2027–2029 Pseudocode Guide, §7.2, pp.20–21.', 'supplementary_targeted_verified', true),
('d0272651-b95a-40be-8485-4d84ae952726'::uuid, 'Pre-condition loop', 'A loop that tests its Boolean condition before each iteration; if the condition is FALSE initially, the body does not run.', 'Hodder 9618 (Watson & Williams, 2019), §11.2.2, p.274; chapter detail; Drive:17qXAmcDsvLV96ytM5w75MWYNsGw9Buf-; Cambridge 9618 Syllabus (2026), p.29; Cambridge 9618 Pseudocode Guide for Teachers (2026), §7.3, p.21; 2027–2029 Pseudocode Guide, §7.3, p.21.', 'supplementary_targeted_verified', true)
)
UPDATE public.glossary_terms AS g
SET term = c.term,
    definition_en = c.definition_en,
    source_ref = c.source_ref,
    definition_evidence_status = c.definition_evidence_status,
    is_glossary_visible = c.is_glossary_visible
FROM changes AS c
WHERE g.id = c.id
RETURNING g.id, g.term, g.definition_evidence_status, g.is_glossary_visible;
